const d = $input.item.json || {};
const err = d.error || {};
const wf = d.workflow || {};

return {
  json: {
    timestamp: new Date().toISOString(),
    workflowName: wf.name || 'Unknown Workflow',
    workflowId: wf.id || '',
    executionId: d.execution?.id || d.id || '',
    failedNode: err.node?.name || d.lastNodeExecuted || '',
    errorMessage: err.message || d.message || 'Unknown error',
    errorType: err.name || d.name || '',
    stack: (err.stack || '').toString().substring(0, 5000)
  }
};

const d = $input.item.json || {};
let form = {};
let workDrive = {};
try {
  workDrive = $('Prepare WorkDrive Files').item.json || {};
} catch (e) {
  workDrive = {};
}

const resumeText = (d.text || '').substring(0, 12000);

let candidateName = d['Full Name'] || form['Full Name'] || '';
let email = d['Email Address'] || form['Email Address'] || '';
let phone = d['Phone Number'] || form['Phone Number'] || '';
let position = d['Position Applied For'] || form['Position Applied For'] || '';
let linkedin = d['LinkedIn Profile'] || form['LinkedIn Profile'] || '';
const yearsOfExp = d['Years of Experience'] || form['Years of Experience'] || 0;

if (!email) {
  const emailPatterns = [
    /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/,
    /email[:\s]*([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,})/i,
    /([A-Za-z0-9._%+-]+@gmail\.com)/i,
    /([A-Za-z0-9._%+-]+@yahoo\.com)/i,
    /([A-Za-z0-9._%+-]+@outlook\.com)/i,
  ];
  for (const pattern of emailPatterns) {
    const match = resumeText.match(pattern);
    if (match) {
      email = match[match.length - 1];
      if (email && email.includes('@')) break;
    }
  }
  if (!email) email = '';
}

if (!candidateName) {
  const nameLine = (resumeText.split('\n')[0] || '').trim();
  if (nameLine && nameLine.length > 2 && nameLine.length < 60 && !nameLine.includes('@') && !nameLine.match(/\d+/)) {
    candidateName = nameLine;
  }
  if (!candidateName) {
    const regardsPatterns = [/(?:regards|sincerely|best regards|kind regards|warm regards|yours)[,\s]+([A-Za-z\s]+)/i];
    for (const pattern of regardsPatterns) {
      const match = resumeText.match(pattern);
      if (match) {
        const name = match[match.length - 1].trim();
        if (name.length > 2 && name.length < 60 && !name.includes('@') && !name.match(/^[0-9]+$/)) {
          candidateName = name;
          break;
        }
      }
    }
  }
  if (!candidateName) candidateName = 'Unknown';
}

if (!phone) {
  const phonePatterns = [
    /(?:phone|mobile|ph|tel|contact)[:\s]+([\d\s\-\(\)\+\.]+(?:\d{7,15}))/i,
    /(\+\d{1,3}[\s.-]?\d{1,4}[\s.-]?\d{1,9})/,
    /(\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4})/,
    /(\d{1,3}[\s.-]?\d{3,4}[\s.-]?\d{4,5})/,
  ];
  for (const pattern of phonePatterns) {
    const match = resumeText.match(pattern);
    if (match) {
      phone = match[match.length - 1].trim().replace(/^[^\d\+]/g, '');
      if (phone.match(/\d{7,}/)) break;
    }
  }
}

if (!linkedin) {
  const linkedinPatterns = [/linkedin\.com\/in\/([\w\-]+)/i, /li\.in\/([\w\-]+)/i];
  for (const pattern of linkedinPatterns) {
    const match = resumeText.match(pattern);
    if (match) {
      linkedin = match[0].includes('linkedin.com') ? 'https://' + match[0] : 'https://linkedin.com/in/' + match[1];
      break;
    }
  }
}

if (!position) position = 'Not Specified';

return {
  json: {
    source: workDrive.source || d.source || 'form',
    candidateName,
    email,
    phone: phone || '',
    position,
    yearsOfExp,
    linkedin: linkedin || '',
    resumeText,
    workdriveFileId: workDrive.fileId || d.workdriveFileId || d.resourceId || '',
    workdriveFileName: workDrive.fileName || d.workdriveFileName || d.fileName || '',
    sourceFolderId: workDrive.sourceFolderId || d.sourceFolderId || '',
    processedFolderId: workDrive.processedFolderId || d.processedFolderId || '',
    submittedAt: new Date().toISOString(),
  },
};

const d = $input.item.json;
const fromRaw   = d.from || '';
const senderEmail= (fromRaw.match(/<(.+?)>/) || [])[1] || fromRaw;
const resumeText = (d.text || '').substring(0, 12000);

// Extract email from resume
let extractedEmail = '';
const emailPatterns = [
  /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/,
  /email[:\s]*([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,})/i,
  /([A-Za-z0-9._%+-]+@gmail\.com)/i,
  /([A-Za-z0-9._%+-]+@yahoo\.com)/i,
  /([A-Za-z0-9._%+-]+@outlook\.com)/i
];
for (const pattern of emailPatterns) {
  const match = resumeText.match(pattern);
  if (match) {
    extractedEmail = match[match.length - 1];
    if (extractedEmail && extractedEmail.includes('@')) break;
  }
}
const finalEmail = extractedEmail || senderEmail;

// Extract name
let candidateName = fromRaw.replace(/<.*>/, '').trim() || 'Unknown';
const nameLine = (resumeText.split('\n')[0] || '').trim();
if (nameLine && nameLine.length > 2 && nameLine.length < 60 && !nameLine.includes('@') && !nameLine.match(/\d+/)) {
  candidateName = nameLine;
}

// Extract phone
let phone = '';
const phonePatterns = [
  /(?:phone|mobile|ph|tel|contact)[:\s]+([\d\s\-\(\)\+\.]+(?:\d{7,15}))/i,
  /(\+\d{1,3}[\s.-]?\d{1,4}[\s.-]?\d{1,9})/,
  /(\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4})/,
  /(\d{1,3}[\s.-]?\d{3,4}[\s.-]?\d{4,5})/
];
for (const pattern of phonePatterns) {
  const match = resumeText.match(pattern);
  if (match) {
    phone = match[match.length - 1].trim().replace(/^[^\d\+]/g, '');
    if (phone.match(/\d{7,}/)) break;
  }
}

// Extract LinkedIn
let linkedin = '';
const linkedinPatterns = [
  /linkedin\.com\/in\/([\w\-]+)/i,
  /li\.in\/([\w\-]+)/i
];
for (const pattern of linkedinPatterns) {
  const match = resumeText.match(pattern);
  if (match) {
    linkedin = match[0].includes('linkedin.com') ? 'https://' + match[0] : 'https://linkedin.com/in/' + match[1];
    break;
  }
}

// Position from subject
let position = 'Open Application';
const subject = (d.subject || '').trim();
if (subject && subject.length > 3) {
  let cleanSubject = subject.replace(/^(re|fwd|fw)[:\s]?/gi, '').trim();
  const fieldPattern = /(?:position|role|designation|apply|applying)[:\s]+([^-\n]+)/i;
  const fieldMatch = cleanSubject.match(fieldPattern);
  if (fieldMatch && fieldMatch[1]) {
    position = fieldMatch[1].trim();
    if (position.length < 2 || position.length > 100) position = 'Open Application';
  }
  if (position === 'Open Application') {
    const keywords = ['frontend developer','backend developer','fullstack developer','full stack developer','devops engineer','qa engineer','software engineer','data scientist','cloud architect','senior developer','junior developer','developer','engineer','analyst','manager','architect','designer'];
    for (const keyword of keywords) {
      if (cleanSubject.toLowerCase().includes(keyword)) {
        position = keyword.charAt(0).toUpperCase() + keyword.slice(1);
        break;
      }
    }
  }
  if (position === 'Open Application') {
    position = cleanSubject.replace(/application|resume|cv|curriculum|vitae/gi, '').trim();
    if (position.length < 2 || position.length > 100) position = 'Open Application';
  }
}

return {
  json: {
    source:        'email',
    candidateName: candidateName,
    email:         finalEmail,
    phone:         phone,
    position:      position,
    yearsOfExp:    0,
    linkedin:      linkedin,
    resumeText:    resumeText,
    submittedAt:   new Date().toISOString()
  }
};

const d = { ...$input.item.json };
delete d.resumeText;
return { json: d };

// Parse and Average Scores - fixed version
// Outputs fields matching the candidates table and preserves WorkDrive metadata

const d = $input.item.json;

const fromNode = (name) => {
  try { return $(name).item.json || {}; } catch (e) { return {}; }
};

const triggers = fromNode('Merge Triggers');
const extracted = fromNode('Extract \u2014 All Skills & Details');
const jdNode = fromNode('Pre-filled JD');
const promptNode = fromNode('Build Scoring Prompt (/100)');

const m = { ...triggers, ...extracted, ...jdNode, ...promptNode, ...d };

const clean = (v) => String(v ?? '').trim();
const hasNum = (v) => v !== undefined && v !== null && v !== '' && !Number.isNaN(Number(v));
const first = (...vals) => vals.find((v) => v !== undefined && v !== null && v !== '');
const pickStr = (...vals) => {
  const found = vals
    .map(clean)
    .find((v) => v && v.toLowerCase() !== 'n/a' && v.toLowerCase() !== 'none' && v !== 'undefined');
  return found || '';
};

let remote = {};
try {
  const rawRemote = first(
    d.text, d.text1, d.text2,
    d.output, d.output1, d.output2,
    d.response?.text, d.response1?.text, d.response2?.text,
    (d.choices || [])[0]?.message?.content,
  );
  if (rawRemote !== undefined) {
    const cleaned = String(rawRemote)
      .replace(/```json\s*/gi, '')
      .replace(/```\s*/g, '')
      .replace(/^[^{]*/, '')
      .replace(/[^}]*$/, '');
    remote = JSON.parse(cleaned);
  }
} catch (e) {
  remote = {};
}

let local = {};
try {
  const rawLocal = first(
    d.response, d.response1, d.response2,
    d.message?.content, d.message1?.content, d.message2?.content,
  );
  if (rawLocal !== undefined && rawLocal !== first(d.text, d.text1, d.text2)) {
    local = typeof rawLocal === 'string' ? JSON.parse(rawLocal) : rawLocal;
  }
} catch (e) {
  local = {};
}

const textBlob = [
  m.resumeText, m.programmingLanguages, m.programmingLangs,
  m.frontendSkills, m.backendSkills, m.databaseSkills,
  m.aiMlSkills, m.cloudDevOps,
].map((v) => clean(v).toLowerCase()).join(' ');

const detect = (items) => items.filter((s) => textBlob.includes(s.toLowerCase()));
const detectedFE = detect(['React', 'Angular', 'Vue', 'Next.js', 'HTML', 'CSS', 'JavaScript', 'TypeScript', 'jQuery', 'Bootstrap', 'Tailwind']);
const detectedBE = detect(['Node.js', 'Express', 'Java', 'Spring', 'Python', 'Django', 'Flask', 'PHP', 'Laravel', 'REST', 'API', 'NestJS', 'FastAPI']);
const detectedDB = detect(['MySQL', 'PostgreSQL', 'MongoDB', 'SQLite', 'Redis', 'Firebase', 'Oracle', 'SQL', 'DynamoDB']);
const detectedAI = detect(['AI', 'ML', 'TensorFlow', 'PyTorch', 'OpenAI', 'ChatGPT', 'LangChain', 'NLP', 'GPT', 'LLM', 'Machine Learning']);

const floorFE = detectedFE.length >= 3 ? 10 : detectedFE.length >= 1 ? 6 : 0;
const floorBE = detectedBE.length >= 3 ? 10 : detectedBE.length >= 1 ? 6 : 0;
const floorDB = detectedDB.length >= 2 ? 8 : detectedDB.length >= 1 ? 5 : 0;
const floorAI = detectedAI.length >= 2 ? 5 : detectedAI.length >= 1 ? 3 : 0;

const pickScore = (field, max, floor) => {
  const l = hasNum(local[field]) ? Number(local[field]) : null;
  const r = hasNum(remote[field]) ? Number(remote[field]) : null;
  let value = 0;
  if (l !== null && r !== null) value = (l + r) / 2;
  else if (r !== null) value = r;
  else if (l !== null) value = l;
  value = Math.max(value, floor);
  return Math.round(Math.min(value, max) * 10) / 10;
};

const frontend_score = pickScore('frontendScore', 25, floorFE);
const backend_score = pickScore('backendScore', 25, floorBE);
const database_score = pickScore('databaseScore', 20, floorDB);
const ai_ml_score = pickScore('aiMlScore', 15, floorAI);
const exp_score = pickScore('experienceScore', 10, 2);
const soft_score = pickScore('softSkillsScore', 5, 2);
const total_score = Math.round(frontend_score + backend_score + database_score + ai_ml_score + exp_score + soft_score);

const grade =
  total_score >= 90 ? 'A+' :
  total_score >= 80 ? 'A' :
  total_score >= 70 ? 'B+' :
  total_score >= 60 ? 'B' :
  total_score >= 50 ? 'C' :
  total_score >= 40 ? 'D' : 'F';

const recommendation =
  total_score >= 80 ? 'Strong Hire' :
  total_score >= 65 ? 'Hire' :
  total_score >= 45 ? 'Consider' : 'Reject';

const toArr = (v) => Array.isArray(v) ? v : (typeof v === 'string' && v.includes('|') ? v.split('|').map((s) => s.trim()) : []);
const strengths = [...new Set([...toArr(remote.strengths), ...toArr(local.strengths)])].filter(Boolean).slice(0, 5);
const weaknesses = [...new Set([...toArr(remote.weaknesses), ...toArr(local.weaknesses)])].filter(Boolean).slice(0, 5);

const frontendSkillsVal = pickStr(m.frontendSkills, detectedFE.join(', '));
const backendSkillsVal = pickStr(m.backendSkills, detectedBE.join(', '));
const databaseSkillsVal = pickStr(m.databaseSkills, detectedDB.join(', '));
const frontendLevelVal = pickStr(m.frontendLevel, detectedFE.length >= 3 ? 'intermediate' : detectedFE.length ? 'beginner' : '');
const backendLevelVal = pickStr(m.backendLevel, detectedBE.length >= 3 ? 'intermediate' : detectedBE.length ? 'beginner' : '');
const databaseLevelVal = pickStr(m.databaseLevel, detectedDB.length >= 2 ? 'intermediate' : detectedDB.length ? 'beginner' : '');

return {
  json: {
    submitted_at: pickStr(m.submittedAt, m.submitted_at) || new Date().toISOString(),
    processed_at: new Date().toISOString(),
    source: pickStr(m.source) || 'unknown',

    candidate_name: pickStr(m.candidateName, m.candidate_name) || 'Unknown',
    email: pickStr(m.email) || '',
    phone: pickStr(m.phone) || '',
    position: pickStr(m.position) || '',
    years_of_exp: Number(m.totalExperienceYears || m.yearsOfExp || m.years_of_exp || 0),
    linkedin: pickStr(m.linkedin) || '',
    current_job_title: pickStr(m.currentJobTitle, m.current_job_title) || '',
    highest_degree: pickStr(m.highestDegree, m.highest_degree) || '',
    certifications: pickStr(m.certifications) || '',

    frontend_skills: frontendSkillsVal,
    frontend_level: frontendLevelVal,
    backend_skills: backendSkillsVal,
    backend_level: backendLevelVal,
    database_skills: databaseSkillsVal,
    database_level: databaseLevelVal,
    ai_ml_skills: pickStr(m.aiMlSkills, m.ai_ml_skills) || '',
    ai_ml_level: pickStr(m.aiMlLevel, m.ai_ml_level) || '',
    cloud_devops: pickStr(m.cloudDevOps, m.cloud_devops) || '',
    programming_langs: pickStr(m.programmingLanguages, m.programmingLangs, m.programming_langs) || '',
    notable_projects: pickStr(m.notableProjects, m.notable_projects) || '',

    jd_title: pickStr(m.jd_title, m.jdTitle) || '',
    jd_company: pickStr(m.jd_company, m.jdCompany) || '',

    total_score,
    frontend_score,
    backend_score,
    database_score,
    ai_ml_score,
    exp_score,
    soft_score,

    grade,
    recommendation,
    is_qualified: total_score >= 50,

    summary: pickStr(remote.summary, local.summary) || '',
    strengths: strengths.join(' | ') || '',
    weaknesses: weaknesses.join(' | ') || '',
    frontend_feedback: pickStr(remote.frontendFeedback, local.frontendFeedback) || '',
    backend_feedback: pickStr(remote.backendFeedback, local.backendFeedback) || '',
    database_feedback: pickStr(remote.databaseFeedback, local.databaseFeedback) || '',
    ai_ml_feedback: pickStr(remote.aiMlFeedback, local.aiMlFeedback) || '',
    hiring_note: pickStr(remote.hiringNote, local.hiringNote) || '',

    workdrive_file_id: pickStr(m.workdriveFileId, m.workdrive_file_id) || '',
    workdrive_file_name: pickStr(m.workdriveFileName, m.workdrive_file_name) || '',
    source_folder_id: pickStr(m.sourceFolderId, m.source_folder_id) || '',
    processed_folder_id: pickStr(m.processedFolderId, m.processed_folder_id) || '',
  },
};

